import { redisService } from "@redis/index.js";
import { getAdminRefreshTokenKey } from "@redis/keys/redis.keys.js";
import { ADMIN_REFRESH_TOKEN_TTL } from "@redis/ttls/ttl.constants.js";
import { logger } from "@logger/logger.js";

// ═══════════════════════════════════════════════════════════════════
// ADMIN TOKEN REVOCATION SERVICE
//
// Centralizes the Redis-backed refresh-token tracking used to revoke
// admin JWTs. Access and refresh tokens generated by
// `generateAdminTokens` share the same base jti ("access_<base>" and
// "refresh_<base>"). We persist the valid refresh jti per admin so that:
//
//   • Logout can delete it (immediate revocation)
//   • Password change/reset can delete it (invalidate all sessions)
//   • The REST/GraphQL guards can verify an access token's correlated
//     refresh jti is still the one stored in Redis
//   • Token refresh can confirm the presented refresh jti is still valid
//
// Only ONE refresh token is valid per admin at a time. Issuing new
// tokens overwrites the stored jti, which naturally rotates/invalidates
// any previously issued session.
// ═══════════════════════════════════════════════════════════════════

/**
 * Normalise any token jti to its refresh form.
 * - "access_abc"  -> "refresh_abc"
 * - "refresh_abc" -> "refresh_abc"
 */
export function toRefreshJti(jti: string | undefined | null): string | null {
  if (!jti) return null;
  if (jti.startsWith("refresh_")) return jti;
  if (jti.startsWith("access_")) return jti.replace(/^access_/, "refresh_");
  return null;
}

/**
 * Store (or overwrite) the valid refresh jti for an admin.
 * Called on login, onboarding confirmation, and token refresh.
 */
export async function storeAdminRefreshJti(
  userId: string,
  refreshJti: string,
): Promise<void> {
  await redisService.set(
    getAdminRefreshTokenKey(userId),
    refreshJti,
    "EX",
    ADMIN_REFRESH_TOKEN_TTL,
  );
  logger.debug("Stored admin refresh jti in Redis", { userId });
}

/**
 * Fetch the currently valid refresh jti for an admin.
 * Returns null if the session has been revoked or expired.
 */
export async function getStoredAdminRefreshJti(
  userId: string,
): Promise<string | null> {
  return redisService.get(getAdminRefreshTokenKey(userId));
}

/**
 * Check whether a given refresh jti is the one currently stored for the
 * admin. Used by guards and the refresh endpoint.
 */
export async function isAdminRefreshJtiValid(
  userId: string,
  refreshJti: string,
): Promise<boolean> {
  const stored = await getStoredAdminRefreshJti(userId);
  return !!stored && stored === refreshJti;
}

/**
 * Revoke all refresh tokens for an admin by deleting the stored jti.
 * Called on logout, password change, and password reset.
 */
export async function revokeAdminRefreshTokens(userId: string): Promise<void> {
  await redisService.delete(getAdminRefreshTokenKey(userId));
  logger.debug("Revoked admin refresh tokens in Redis", { userId });
}
